      pa: 'CPU ਅਤੇ ਮੁੱਖ ਮੈਮੋਰੀ (RAM) ਵਿਚਕਾਰ ਸੰਪਰਕ ਕਰਨ ਵਾਲੀਆਂ ਤਿੰਨ ਸਿਸਟਮ ਬੱਸਾਂ (Address Bus, Data Bus, Control Bus) ਵਿੱਚੋਂ ਕਿਹੜੀ ਬੱਸ ਸਿਰਫ਼ "ਇੱਕ-ਦਿਸ਼ਾਵੀ" (Unidirectional) ਹੁੰਦੀ ਹੈ?',
